    'set.open_disclaimer': 'Open disclaimer',

    /* ---------- legal modal ---------- */
    'legal.title': 'What TIKOTrade is — and is not',
    'legal.p1': 'TIKOTrade is an informational tool. It describes market setups using fixed, rule-based calculations over a price series — trend, momentum, volatility, structure and volume — and ranks those setups on the Ideas page. The ranking is educational and rules-based: it is not personalized investment advice, a ratings service, a price forecast or a guarantee of returns. The app has no brokerage connection and cannot place an order; the bot and its ledger are simulations that stay in your browser.',
    'legal.p2': 'Every analysis is a snapshot. Data may be delayed, incomplete or — where explicitly labeled — synthetic. When you see the SAMPLE badge, no real market data is involved. Where live data is shown, it comes from public APIs that can be rate limited or lag an exchange feed.',
    'legal.p3': 'Signals are not forecasts. A bullish or bearish lean describes the balance of evidence at one moment, with a confidence level. Markets can move against any setup, including through events this tool does not model, such as news, earnings, macro releases, liquidity shocks or gaps.',
    'legal.p4': 'You are responsible for your own decisions, position sizing and risk. Consider seeking advice from a licensed professional who knows your circumstances. Past behavior and historical structure do not guarantee future results.',
    'legal.p5': 'TIKOTrade does not require an account or send credentials to a server. Settings, watchlists, notes and feedback are stored in this browser on this device and are not encrypted; anyone with access to this browser profile may be able to see them. The optional Alpha Vantage key is kept in tab storage and cleared when the tab ends. Market-data requests go from your browser to the named providers or to TIKOTrade’s own stock-quote proxy, which forwards anonymous symbol requests to Yahoo Finance.',

    /* ---------- glossary ---------- */
    'g.trend': 'Trend',
    'g.trend.def': 'The prevailing direction of price over a chosen window. Here it is inferred from price versus its moving averages and the slope of those averages — a description of the past, not a forecast.',
    'g.support': 'Support',
    'g.support.def': 'A price area where buyers have previously stepped in, slowing or reversing declines. It is a zone, not a precise line.',
    'g.resistance': 'Resistance',
    'g.resistance.def': 'A price area where sellers have previously appeared, capping rallies. Old resistance can become support after a clean break.',
    'g.volatility': 'Volatility',
    'g.volatility.def': 'How much price moves, typically measured by the standard deviation of returns. Higher volatility means wider normal swings and requires smaller position sizes for the same risk.',
    'g.liquidity': 'Liquidity',
    'g.liquidity.def': 'How easily you can trade size without moving the price. Thin liquidity means wider spreads, worse fills and bigger reactions to modest orders.',
    'g.momentum': 'Momentum',
    'g.momentum.def': 'The speed and persistence of recent moves, often measured with returns and RSI. Momentum describes recent behavior; it says nothing about value.',
    'g.rsi': 'RSI',
    'g.rsi.def': 'Relative Strength Index, a 0–100 momentum oscillator. Above 70 is often read as stretched to the upside, below 30 as stretched to the downside. Strong trends can stay stretched for a long time.',
    'g.sma': 'Moving average',
    'g.sma.def': 'The average close over the last N bars. Comparing price to a moving average is a simple way to describe trend; the average itself lags price.',
    'g.atr': 'ATR',
    'g.atr.def': 'Average True Range: the typical size of a bar including gaps. Useful for placing stops outside normal noise rather than at arbitrary distances.',
    'g.realized_vol': 'Realized volatility',
    'g.realized_vol.def': 'The volatility that actually occurred over a window, annualized. It is backwards-looking and differs from implied volatility, which is what options prices imply about the future.',
    'g.drawdown': 'Drawdown',
    'g.drawdown.def': 'The decline from a prior peak to the current price, in percent. A deep drawdown means the asset is far below its high, not necessarily that it is cheap.',
    'g.swing': 'Swing trading',
    'g.swing.def': 'Holding positions for days to weeks to capture a move, rather than intraday or multi-year. Swing analysis weights trend and momentum over intraday noise.',
    'g.intraday': 'Intraday',
    'g.intraday.def': 'Within a single trading session. Intraday analysis focuses on session levels, ranges and volume, and its signals decay fast.',
    'g.invalidation': 'Invalidation',
    'g.invalidation.def': 'The price at which your current reasoning stops being valid. Defining it before entering is what turns a view into a bounded risk.',
    'g.gap': 'Gap',
    'g.gap.def': 'A jump between one bar’s close and the next bar’s open, often caused by news while a market was closed. Gaps can jump through stop orders.',
    'g.volume': 'Volume',
    'g.volume.def': 'How much was traded in a period. Moves on above-average volume are usually considered more meaningful than moves on thin volume.',
    'g.market_cap': 'Market cap',
    'g.market_cap.def': 'Price multiplied by circulating supply. A rough size measure; it does not tell you whether an asset is fairly valued.',
    'g.turnover': 'Turnover',
    'g.turnover.def': 'Traded value relative to market cap. Low turnover can signal thin interest or a tightly held asset.',
    'g.implied_vol': 'Implied volatility',
    'g.implied_vol.def': 'The future volatility implied by option prices. Not connected in this MVP; realized volatility is shown only as a coarse proxy.',
    'g.catalyst': 'Catalyst',
    'g.catalyst.def': 'A scheduled or unscheduled event that can change a market’s direction — earnings, macro data, a court ruling or a protocol upgrade.',
    'g.percentile': 'Percentile',
    'g.percentile.def': 'Where a value sits within its own history. A 90th-percentile volatility reading means the current level is higher than 90% of past readings in the window.',
    'g.zscore': 'Z-score',
    'g.zscore.def': 'Distance from the average measured in standard deviations. It standardizes moves so different markets and windows can be compared.',
    'g.rr': 'Reward-to-risk',
    'g.rr.def': 'Potential gain divided by potential loss from a defined entry and invalidation. The analysis shows distances to levels so you can estimate it yourself.',

    'plan.eyebrow': 'Trade guidance',
    'plan.title': 'Your trade plan',
    'plan.sub': 'Choose Buy or Sell to get a conditional entry plan, risk limits, and practical next steps.',
    'plan.steps.title': 'What to do next',
    'plan.steps.entry': 'Entry decision',
    'plan.steps.risk': 'Set your risk limits',
