    'bot.rules.1': 'Each scan runs the same local analysis and plan rules used on the Analysis page — no model, no cloud, no randomness.',
    'bot.rules.2': 'Tiko scouts the ranked stock list when auto-scouting is on, then only enters when the plan is active or its breakout trigger has fired, evidence is at least medium, and reward is at least 1.3× risk.',
    'bot.rules.3': 'Entries are timed: a live or fired trigger ranks first, and a setup within 0.35× ATR of its trigger is "armed" and queued next. Size uses Settings, capped at the virtual balance. No leverage.',
    'bot.rules.4': 'Tiko closes on its own at the plan stop, the target, or when the plan flips. Once a trade is up 1R the stop moves to breakeven; at 1.5R it trails half a risk unit behind.',
