    'an.method.title': 'Método',
    'an.method.body': 'Señales fijas basadas en reglas calculadas en tu navegador: medias simples y exponenciales, RSI(14), volatilidad realizada, pivotes de giro, ratios de volumen y distancia a la estructura. Nada lo genera un LLM y esta app no envía nada a un servidor.',
