    'lens.day.title': 'Enfoque intradía',
    'lens.day.lede.crypto': 'Cripto opera sin horario, así que no hay campana de apertura. La liquidez se adelgaza en la ventana nocturna UTC, cuando son más comunes las cacerías de stops y los huecos.',
    'lens.day.lede.stock': 'La sesión regular de EE. UU. va de 09:30 a 16:00 hora de Nueva York. Ahora mismo está {{session}}. El intradía se fija en el rango de apertura, el volumen de sesión y la distancia al cierre anterior.',
    'lens.day.b1': 'El rango típico por barra es de unos {{range}}. Un stop más ajustado queda dentro del ruido normal.',
