    'lens.swing.title': 'Enfoque swing',
    'lens.swing.lede': 'La vista swing busca movimientos que duran días o semanas. La alineación de tendencia y el impulso pesan más que el ruido intradía, y un catalizador suele convertir una deriva en un movimiento.',
    'lens.swing.b1': 'Tendencia: {{trend}}, con el precio {{d}} respecto a su media de 50 barras.',
