    'lens.long.title': 'Enfoque de largo plazo',
    'lens.long.lede': 'Las decisiones de largo plazo dependen de valoración y calidad del negocio, algo que este MVP no cubre. Lo que sí muestra es la estructura del precio, la caída desde máximos y el régimen de volatilidad actual.',
    'lens.long.b1': 'El precio está {{dd}} por debajo de su máximo de {{window}} barras y {{dl}} por encima de su mínimo.',
