    'lens.options.title': 'Enfoque de opciones',
    'lens.options.lede': 'Valorar opciones requiere una cadena — volatilidad implícita, sesgo e interés abierto — y ninguna está conectada en este MVP. Se muestra una aproximación con volatilidad realizada, claramente etiquetada como estimación.',
