    'set.cleared': 'Datos locales eliminados.',
    'set.version': 'Versión 1.0 MVP',
    'set.engine': 'Motor de análisis',
    'set.engine.d': 'Basado en reglas v1 — tendencia, impulso, volatilidad, estructura. Sin LLM ni llamadas a servidores desde esta app.',
    'set.legal': 'Legal',
    'set.legal.d': 'Lee qué es y qué no es el análisis.',
    'set.open_disclaimer': 'Abrir aviso legal',

    'legal.title': 'Qué es TIKOTrade — y qué no es',
    'legal.p1': 'TIKOTrade es una herramienta informativa. Describe configuraciones de mercado mediante cálculos fijos basados en reglas sobre una serie de precios — tendencia, impulso, volatilidad, estructura y volumen — y clasifica esas configuraciones en la página Ideas. La clasificación es educativa y basada en reglas: no es asesoramiento de inversión personalizado, un servicio de calificaciones, una previsión de precio ni una garantía de rendimiento. La app no tiene conexión con ningún bróker y no puede enviar órdenes; el bot y su libro son simulaciones que se quedan en tu navegador.',
    'legal.p2': 'Cada análisis es una instantánea. Los datos pueden estar retrasados, incompletos o — cuando se indica — ser sintéticos. Si ves la etiqueta SAMPLE, no hay datos reales de mercado. Cuando se muestran datos en vivo, provienen de APIs públicas que pueden limitarse por tasa o ir por detrás de un feed de exchange.',
    'legal.p3': 'Las señales no son previsiones. Una inclinación alcista o bajista describe el equilibrio de la evidencia en un momento, con un nivel de confianza. El mercado puede moverse contra cualquier situación, incluso por eventos que esta herramienta no modela, como noticias, resultados, datos macro, shocks de liquidez o huecos.',
    'legal.p4': 'Eres responsable de tus propias decisiones, del tamaño de posición y del riesgo. Considera buscar asesoramiento de un profesional autorizado que conozca tu situación. El comportamiento pasado y la estructura histórica no garantizan resultados futuros.',
    'legal.p5': 'TIKOTrade no requiere una cuenta ni envía credenciales a un servidor. Los ajustes, las listas, las notas y los comentarios se guardan en este navegador y dispositivo, sin cifrado; otras personas con acceso a este perfil del navegador podrían verlos. La clave opcional de Alpha Vantage se guarda en la pestaña y se borra al cerrarla. Las solicitudes de datos van desde el navegador a los proveedores indicados o al proxy de cotizaciones propio de TIKOTrade, que reenvía símbolos anónimos a Yahoo Finance.',

    'g.trend': 'Tendencia',
    'g.trend.def': 'La dirección predominante del precio en una ventana elegida. Aquí se infiere comparando el precio con sus medias móviles y la pendiente de esas medias — una descripción del pasado, no una previsión.',
    'g.support': 'Soporte',
    'g.support.def': 'Una zona de precio donde los compradores han intervenido antes, frenando o revirtiendo caídas. Es una zona, no una línea exacta.',
    'g.resistance': 'Resistencia',
    'g.resistance.def': 'Una zona de precio donde han aparecido vendedores antes, limitando las subidas. Una resistencia antigua puede convertirse en soporte tras una ruptura limpia.',
    'g.volatility': 'Volatilidad',
    'g.volatility.def': 'Cuánto se mueve el precio, normalmente medido por la desviación estándar de los retornos. Más volatilidad implica oscilaciones normales más amplias y exige posiciones más pequeñas para el mismo riesgo.',
    'g.liquidity': 'Liquidez',
    'g.liquidity.def': 'La facilidad para operar tamaño sin mover el precio. Poca liquidez significa spreads más amplios, peores ejecuciones y reacciones mayores a órdenes modestas.',
    'g.momentum': 'Impulso',
    'g.momentum.def': 'La velocidad y persistencia de los movimientos recientes, a menudo medida con retornos y RSI. Describe el comportamiento reciente; no dice nada sobre el valor.',
    'g.rsi': 'RSI',
    'g.rsi.def': 'Índice de Fuerza Relativa, un oscilador de impulso entre 0 y 100. Por encima de 70 suele leerse como estirado al alza y por debajo de 30 como estirado a la baja. Las tendencias fuertes pueden seguir estiradas mucho tiempo.',
    'g.sma': 'Media móvil',
    'g.sma.def': 'El cierre medio de las últimas N barras. Comparar el precio con una media es una forma sencilla de describir la tendencia; la media va por detrás del precio.',
    'g.atr': 'ATR',
    'g.atr.def': 'Average True Range: el tamaño típico de una barra incluyendo huecos. Sirve para colocar stops fuera del ruido normal en lugar de a distancias arbitrarias.',
    'g.realized_vol': 'Volatilidad realizada',
    'g.realized_vol.def': 'La volatilidad que realmente ocurrió en una ventana, anualizada. Mira al pasado y difiere de la implícita, que es la que descuentan los precios de las opciones sobre el futuro.',
    'g.drawdown': 'Caída desde máximos',
    'g.drawdown.def': 'El descenso desde un pico previo hasta el precio actual, en porcentaje. Una caída profunda significa que el activo está lejos de su máximo, no necesariamente que esté barato.',
    'g.swing': 'Trading swing',
    'g.swing.def': 'Mantener posiciones de días a semanas para capturar un movimiento, en lugar de intradía o varios años. El análisis swing pondera tendencia e impulso por encima del ruido intradía.',
    'g.intraday': 'Intradía',
    'g.intraday.def': 'Dentro de una misma sesión. El análisis intradía se centra en niveles de sesión, rangos y volumen, y sus señales caducan rápido.',
    'g.invalidation': 'Invalidación',
    'g.invalidation.def': 'El precio en el que tu razonamiento actual deja de ser válido. Definirlo antes de entrar es lo que convierte una visión en un riesgo acotado.',
    'g.gap': 'Hueco',
    'g.gap.def': 'Un salto entre el cierre de una barra y la apertura de la siguiente, a menudo por noticias con el mercado cerrado. Los huecos pueden saltarse las órdenes de stop.',
    'g.volume': 'Volumen',
    'g.volume.def': 'Cuánto se negoció en un periodo. Los movimientos con volumen por encima de la media suelen considerarse más significativos que los de volumen fino.',
    'g.market_cap': 'Capitalización',
    'g.market_cap.def': 'Precio multiplicado por la oferta circulante. Una medida aproximada de tamaño; no dice si un activo está bien valorado.',
    'g.turnover': 'Rotación',
    'g.turnover.def': 'Valor negociado en relación con la capitalización. Una rotación baja puede indicar poco interés o un activo muy concentrado.',
    'g.implied_vol': 'Volatilidad implícita',
    'g.implied_vol.def': 'La volatilidad futura que descuentan los precios de las opciones. No está conectada en este MVP; la volatilidad realizada se muestra solo como aproximación gruesa.',
    'g.catalyst': 'Catalizador',
    'g.catalyst.def': 'Un evento programado o no que puede cambiar la dirección de un mercado — resultados, datos macro, una sentencia o una actualización de protocolo.',
    'g.percentile': 'Percentil',
    'g.percentile.def': 'Dónde se sitúa un valor dentro de su propia historia. Un percentil 90 de volatilidad significa que el nivel actual supera al 90% de las lecturas pasadas de la ventana.',
    'g.zscore': 'Puntuación Z',
    'g.zscore.def': 'Distancia a la media medida en desviaciones estándar. Estandariza los movimientos para comparar mercados y ventanas distintas.',
    'g.rr': 'Relación riesgo-retorno',
    'g.rr.def': 'Ganancia potencial dividida por pérdida potencial desde una entrada y una invalidación definidas. El análisis muestra distancias a niveles para que puedas estimarla tú mismo.',

