    'copilot.a.setup.scenario': 'Escenario del lado elegido desde {{entry}}: objetivo {{target}} (movimiento potencial {{gain}}), stop {{stop}} ({{loss}}), relación beneficio-riesgo {{rr}}. Son estimaciones condicionales, no probabilidades pronosticadas.',
    'copilot.a.buySell.lean': 'Boom no te dice si comprar o vender; califica la evidencia. Esa evidencia se inclina ahora {{lean}} (confianza {{conf}}): puntuación alcista {{bull}}, bajista {{bear}}.',
    'copilot.a.buySell.wait': 'El plan se inclina ahora por {{side}} como setup de {{setup}} ({{state}}). Pasos condicionales: espera el gatillo {{t}}, entra en {{e}} solo si el precio cotiza allí, coloca la invalidación en {{s}} y usa {{tg}} como primer objetivo de referencia con relación beneficio-riesgo {{rr}}.',
    'copilot.a.buySell.active': 'El plan se inclina ahora por {{side}} como setup de {{setup}} ({{state}}). El precio ya superó el gatillo, así que la entrada de referencia es {{e}}, la invalidación {{s}}, el primer objetivo {{tg}} y la relación beneficio-riesgo {{rr}}. No añadas a un movimiento extendido.',
    'copilot.a.buySell.extended': 'El setup de {{side}} está extendido: el precio está {{d}} más allá del gatillo {{t}}, así que entrar aquí sería perseguir. Espera una base nueva o un retroceso hacia {{t}} antes de tratar ese nivel como entrada.',
    'copilot.a.buySell.invalidated': 'La idea de {{side}} está invalidada: el precio ya superó {{lv}}, el nivel que el plan usaba como gatillo. No tomes ese lado hasta que se forme un setup nuevo.',
    'copilot.a.buySell.noEdge': 'El plan no tiene operación en este lado a {{p}}: el precio está entre el soporte {{s}} y la resistencia {{r}}, lejos de ambos. Un setup necesitaría un movimiento hacia {{r}} arriba o {{s}} abajo.',
    'copilot.a.buySell.practice': 'La lectura usa datos de muestra, así que es solo práctica: no hay nada accionable que comprar o vender en una serie sintética.',
    'copilot.a.buySell.noSide': 'No hay un lado direccional en el plan, así que ni comprar ni vender tienen una estructura confirmada ahora. Estas son las salidas condicionales para cualquiera de los dos lados.',
