    'brokers.reg.title': 'Qué significa realmente “regulado”',
    'brokers.reg.lede': 'No toda la regulación es igual. Usa esta escala de cinco niveles.',
    'brokers.reg.l1.t': 'Con licencia, segregado y cubierto',
    'brokers.reg.l1.d': 'Un bróker-dealer estadounidense con cobertura SIPC, una firma británica con FSCS o un dealer canadiense con CIPF. La cobertura tiene límites y suele excluir cripto, CFD y malos resultados.',
    'brokers.reg.l2.t': 'Con licencia y segregado, sin compensación',
    'brokers.reg.l2.d': 'Común en Brasil, México, India, EAU, Arabia Saudí, Sudáfrica, Nigeria, Indonesia y Vietnam. La licencia es real; la red de seguridad es más fina.',
    'brokers.reg.l3.t': 'Registrado para una actividad concreta',
    'brokers.reg.l3.d': 'La licencia de sub-bróker digital de la SEC de Nigeria, el registro cripto FIU-IND de India o la licencia VASP de Kenia. Son aprobaciones de AML y conducta, no garantías prudenciales.',
    'brokers.reg.l4.t': 'Entidad offshore de un grupo regulado',
    'brokers.reg.l4.d': 'La marca puede estar regulada por la FCA o CySEC en otro país mientras tu cuenta está con una entidad de Belice, Seychelles, Mauricio o San Vicente. El apalancamiento es mayor y la protección, menor.',
    'brokers.reg.l5.t': 'Sin licencia o clonada',
    'brokers.reg.l5.d': 'Sin licencia verificable, con afirmaciones falsas sobre el regulador o con un sitio que suplanta a una firma autorizada. Evítala.',
    'brokers.reg.rule': 'Regla práctica: el contrato de la cuenta nombra la entidad legal. Comprueba esa entidad —no el grupo— en el registro público del regulador.',
    'brokers.comp.title': 'La compensación no es una garantía de seguridad',
    'brokers.comp.sipc': 'SIPC de EE. UU.: 500.000 USD, incluidos 250.000 USD en efectivo',
    'brokers.comp.fscs': 'FSCS del Reino Unido: 85.000 GBP por reclamante elegible',
    'brokers.comp.eu': 'UE: los planes nacionales varían, a menudo en torno a 20.000 €',
    'brokers.comp.cipf': 'CIPF de Canadá: 1.000.000 CAD',
    'brokers.comp.hk': 'Hong Kong: 500.000 HKD',
    'brokers.comp.most': 'La mayoría de mercados emergentes: sin plan general de compensación. La licencia, las reglas de segregación y el defensor del cliente son las protecciones principales.',
    'brokers.comp.note': 'Los planes cubren activos que faltan en una firma fallida, no pérdidas de mercado, cripto ni CFD.',
    'brokers.verify.title': 'Rutina de verificación',
    'brokers.verify.1': 'Localiza la entidad legal en el contrato de la cuenta o en el pie de la web.',
    'brokers.verify.2': 'Busca esa entidad en el registro público del regulador.',
    'brokers.verify.3': 'Confirma que la licencia cubre los productos que quieres.',
    'brokers.verify.4': 'Revisa la compensación, la segregación de activos de clientes y la custodia.',
    'brokers.verify.5': 'Revisa la propiedad, las cuentas auditadas y el historial sancionador.',
    'brokers.verify.6': 'Busca advertencias de clonación o suplantación y lee las condiciones de retirada, inactividad y margen.',

    'brokers.fees.title': 'Comisiones y trampas de coste',
    'brokers.fees.lede': 'La comisión de portada no sirve para medir el coste. Compara el total para una operación típica.',
    'brokers.fees.taxonomy': 'Tipos de coste',
    'brokers.fees.col': 'Coste',
