    'brokers.fees.traps': 'Ocho trampas de coste',
    'brokers.fees.allin': 'Coste total ilustrativo',
    'brokers.fees.note': 'Estimaciones de planificación, no cotizaciones. Verifica las tarifas vigentes y los impuestos locales.',
    'brokers.fees.scenario': 'Escenario',
    'brokers.fees.rough': 'Total aproximado',
    'brokers.fee.commission': 'Comisión',
    'brokers.fee.commission.d': 'Por orden, porcentaje del valor o por tramos. A menudo cero en entrega de acciones.',
    'brokers.fee.spread': 'Diferencial / margen',
    'brokers.fee.spread.d': 'La diferencia entre compra y venta, o un margen de cambio. El coste principal en brókers de “cero comisión”.',
    'brokers.fee.fx': 'Conversión de divisa',
    'brokers.fee.fx.d': 'Margen al convertir moneda local a USD o EUR. Puede ser del 0,3–3% y se acumula en cada operación.',
    'brokers.fee.custody': 'Custodia / plataforma',
    'brokers.fee.custody.d': 'Cuotas mensuales, trimestrales o sobre activos. Pueden erosionar cuentas pequeñas.',
    'brokers.fee.inactivity': 'Inactividad',
    'brokers.fee.inactivity.d': 'Una cuota mensual tras un periodo sin actividad, común en brókers integrales.',
    'brokers.fee.withdrawal': 'Retirada / ingreso',
    'brokers.fee.withdrawal.d': 'Comisiones bancarias, de tarjeta o de dinero móvil. Los rieles locales son más baratos que las transferencias internacionales.',
    'brokers.fee.financing': 'Financiación / swap',
    'brokers.fee.financing.d': 'Interés de margen y swap nocturno en CFD. Domina las posiciones apalancadas y de larga duración.',
    'brokers.fee.data': 'Datos de mercado',
    'brokers.fee.data.d': 'Suscripciones a datos de exchange y en tiempo real. Importante para traders activos de futuros y opciones.',
    'brokers.fee.taxes': 'Impuestos y tasas',
    'brokers.fee.taxes.d': 'Impuesto de timbre, impuesto de transacciones, STT, GST o IVA. A menudo superan la comisión.',
    'brokers.fee.corporate': 'Acciones corporativas',
    'brokers.fee.corporate.d': 'Reinversión de dividendos, voto por poder y conversiones. Relevante para inversores a largo plazo.',
    'brokers.traps.1': 'Margen de cambio disfrazado de cero comisión. Un 1% sobre una operación de 1.000 USD son 10 USD, a menudo más que una comisión de 5 USD.',
    'brokers.traps.2': 'Comisiones de retirada. Las transferencias internacionales pueden costar 15–40 USD; los rieles locales son más baratos.',
    'brokers.traps.3': 'Comisiones de inactividad. Comunes en brókers integrales y capaces de agotar saldos pequeños.',
    'brokers.traps.4': 'Datos de mercado y cuotas de plataforma. Los traders de futuros y opciones suelen pagar más por datos que por comisiones.',
    'brokers.traps.5': 'Costes de margen y swap. Las posiciones apalancadas pueden perder dinero aunque el precio no se mueva.',
    'brokers.traps.6': 'Impuestos y tasas. STT, timbre, GST, impuestos de transacción y retención de dividendos pueden superar la comisión del bróker.',
    'brokers.traps.7': 'Conversión de divisa al retirar. El margen de salida puede costar tanto como el de entrada.',
    'brokers.traps.8': 'Periodos promocionales de “cero comisión”. Revisa la fecha de fin y el precio que se aplica después.',
    'brokers.allin.india': 'Renta variable nacional en India, ₹50 mil',
    'brokers.allin.indiaUs': 'India → acción de EE. UU. vía LRS',
    'brokers.allin.brazil': 'Renta variable nacional en Brasil',
    'brokers.allin.southAfrica': 'Sudáfrica vía EasyEquities',
    'brokers.allin.uae': 'EAU → acción de EE. UU. vía app',
    'brokers.allin.nigeria': 'Nigeria → acción de EE. UU. vía app',
    'brokers.allin.vietnam': 'Renta variable nacional en Vietnam',
