    'brokers.assets.title': 'Notas por clase de activo',
    'brokers.assets.equities.t': 'Renta variable y ETF',
    'brokers.assets.equities.1': 'Las acciones fraccionadas se permiten en EE. UU. y muchas apps, pero no en India, y su disponibilidad varía en Brasil, México, el CCG y África.',
    'brokers.assets.equities.2': 'La conversión de divisa es el mayor coste oculto de invertir en EE. UU. desde el exterior: un 0,3–1,5% es habitual y un 2–3% es caro.',
    'brokers.assets.equities.3': 'Conviene saber dónde está la custodia —un depositario central local o un nominee/custodio en el exterior— y quién es el beneficiario efectivo.',
    'brokers.assets.equities.4': 'Revisa envolturas fiscales como TFSA (Sudáfrica), APV (Chile), ELSS/NPS (India), PGBL (Brasil), PRS (Malasia) y PERA (Filipinas).',
    'brokers.assets.fx.t': 'FX y CFD',
    'brokers.assets.fx.1': 'El FX apalancado y los CFD están restringidos o prohibidos en India, China, Vietnam y partes del CCG. Verifica la legalidad local antes de fondear.',
    'brokers.assets.fx.2': 'Las entidades minoristas de la UE, Reino Unido y Australia limitan el FX mayor a 30:1 con protección de saldo negativo; las entidades offshore pueden ofrecer 200:1–2.000:1 con menos protección.',
    'brokers.assets.fx.3': 'Los costes de swap y financiación pueden erosionar posiciones largas aunque el precio no se mueva, y los CFD no son adecuados para invertir a largo plazo.',
    'brokers.assets.futures.t': 'Futuros y opciones',
    'brokers.assets.futures.1': 'Las tasas de exchange y cámara, más los datos en tiempo real que a menudo cuestan 10–100+ USD al mes, pueden superar las comisiones de un trader activo.',
    'brokers.assets.futures.2': 'Revisa las reglas de margen y liquidación, los tipos de orden y si el bróker ofrece órdenes bracket o API.',
    'brokers.assets.futures.3': 'India es el mayor mercado minorista de opciones del mundo por volumen de contratos; SEBI ha recortado vencimientos semanales y elevado los lotes mientras aumentaban las pérdidas minoristas.',
    'brokers.assets.crypto.t': 'Cripto',
    'brokers.assets.crypto.1': 'Conviven dos modelos: exchanges locales con licencia y rieles locales, y exchanges globales cuya licencia y acceso varían mucho.',
    'brokers.assets.crypto.2': 'La custodia en el exchange te expone a quiebras, hackeos y bloqueos de retirada; la autocustodia elimina el riesgo de contraparte pero exige disciplina operativa.',
    'brokers.assets.crypto.3': 'La prueba de reservas es útil pero incompleta: no demuestra pasivos ni segregación de activos de clientes.',
    'brokers.assets.crypto.4': 'Las stablecoins dominan el ahorro y las remesas en mercados emergentes, pero conllevan riesgo de emisor, reservas y regulación. El P2P añade riesgo de fraude y AML.',
    'brokers.tax.title': 'Claves fiscales y transfronterizas',
    'brokers.tax.1': 'Los controles de cambio en Nigeria, Argentina, Etiopía, China e India (LRS) pueden ralentizar o complicar la repatriación.',
    'brokers.tax.2': 'Los dividendos estadounidenses suelen retenerse al 30% para no residentes salvo que un tratado lo reduzca; presenta el W-8BEN cuando corresponda.',
    'brokers.tax.3': 'CRS y FATCA hacen que las cuentas de bróker sean cada vez más visibles para las autoridades fiscales, y la declaración cripto se amplía.',
    'brokers.tax.4': 'Una inversión “en dólares” puede perder dinero en moneda local aunque el activo suba.',
    'brokers.tax.5': 'Usa envolturas fiscales cuando existan, pero comprueba que admitan activos extranjeros.',
    'brokers.tax.6': 'La cripto puede tributar como renta, ganancia de capital o ambas. Registra cada operación, transferencia y comisión.',
    'brokers.tax.note': 'Claves indicativas, no asesoramiento fiscal. Consulta a un asesor local.',

    'brokers.check.title': 'Veinte preguntas antes de fondear una cuenta',
    'brokers.check.lede': 'Marca lo que puedas verificar. Cualquier pregunta sin respuesta es motivo para detenerte.',
    'brokers.check.progress': '{{done}} de {{total}} verificadas',
    'brokers.check.reset': 'Reiniciar lista',
    'brokers.check.q1': '¿Quién es la entidad legal que custodiará mi cuenta y dónde está constituida?',
    'brokers.check.q2': '¿Qué regulador le da licencia y cubre esa licencia mis productos?',
    'brokers.check.q3': '¿Está mi dinero segregado de los activos de la firma? ¿Quién es el custodio?',
    'brokers.check.q4': '¿Existe un plan de compensación y qué cubre realmente?',
    'brokers.check.q5': '¿Cuál es el modelo de ejecución: agencia, principal, internalización o pago por flujo de órdenes?',
    'brokers.check.q6': '¿Cuál es el coste total de una operación típica, incluidos FX, diferencial, tasas, custodia y retirada?',
    'brokers.check.q7': '¿Cuál es el margen de conversión de divisa y puedo mantener varias monedas?',
    'brokers.check.q8': '¿Cómo ingreso y retiro fondos, y cuánto tarda?',
    'brokers.check.q9': '¿Hay mínimos, comisiones de inactividad o cuotas de plataforma?',
    'brokers.check.q10': '¿Qué productos puedo acceder realmente desde mi país?',
    'brokers.check.q11': '¿Cuáles son las reglas de margen y liquidación?',
    'brokers.check.q12': '¿Cómo se gestionan dividendos, splits y acciones corporativas?',
    'brokers.check.q13': '¿Qué documentos fiscales recibiré?',
    'brokers.check.q14': '¿Quién gestiona las reclamaciones y existe un defensor del cliente?',
    'brokers.check.q15': '¿Qué tan estable es la plataforma y qué ocurre durante una caída?',
    'brokers.check.q16': '¿Qué protecciones de datos, privacidad y ciberseguridad se aplican?',
    'brokers.check.q17': 'Para cripto: ¿quién custodia las claves, hay prueba de reservas y existe seguro?',
    'brokers.check.q18': '¿Hay restricciones de sanciones o AML para mi país o método de pago?',
    'brokers.check.q19': '¿Puedo transferir mis activos fuera si me voy?',
    'brokers.check.q20': '¿Es sólida financieramente la firma y quién es su propietario?',
    'brokers.red.title': 'Señales de alarma',
    'brokers.red.1': 'Rendimientos garantizados o rentabilidad “sin riesgo”.',
    'brokers.red.2': 'Una entidad sin licencia u offshore sin entrada verificable en el registro.',
    'brokers.red.3': 'Presión para depositar rápido o para reclutar a otras personas.',
    'brokers.red.4': 'Planes de bonos con condiciones de permanencia.',
    'brokers.red.5': 'Retrasos en retiradas o bloqueos de cuenta sin explicación.',
    'brokers.red.6': 'Una web que clona una marca conocida o usa un logo falso de regulador.',
    'brokers.red.7': 'Sin declaración de segregación, sin custodio identificado y sin cuentas auditadas.',
    'brokers.red.8': 'Tipos de “earn” cripto muy por encima del mercado.',
    'brokers.red.9': 'Contrapartes P2P que piden sacar la conversación de la plataforma.',
    'brokers.red.10': 'Desafíos de “prop firm” no regulados presentados como cuentas de bróker.',
