    'brokers.score.funding': 'Rieles y velocidad de ingreso y retirada',
    'brokers.score.platform': 'Fiabilidad de la plataforma, app y API',
    'brokers.score.research': 'Investigación, educación y soporte',
    'brokers.score.tax': 'Informes fiscales y envolturas',
