    'brokers.trends.title': 'Qué está cambiando, 2026–2028',
    'brokers.trends.1': 'Acciones y cripto convergen. Los brókers añaden cripto, las apps cripto añaden acciones tokenizadas y el paquete “super-app” plantea nuevas dudas regulatorias.',
    'brokers.trends.2': 'Las acciones estadounidenses tokenizadas se extienden. Las de Luno en Nigeria son un ejemplo temprano; la adopción depende de la ley de valores, la custodia y las reglas de cambio.',
    'brokers.trends.3': 'Los bancos compran o crean neobrókers mientras suben los costes de cumplimiento, siguiendo casos como Bancolombia–Trii e Itaú–Avenue.',
    'brokers.trends.4': 'Los regímenes cripto se formalizan: las reglas VASP de Brasil, la ISA 2025 de Nigeria, la VASP Act de Kenia, la supervisión de OJK en Indonesia y la ley cripto turca sirven de plantilla.',
    'brokers.trends.5': 'La compresión de comisiones continúa. La renta variable sin comisión se extiende y los ingresos migran a FX, margen, fondos y suscripciones.',
    'brokers.trends.6': 'Los derivados minoristas y el apalancamiento enfrentan límites más estrictos en India, Turquía y Europa, con más margen y controles de idoneidad.',
    'brokers.trends.7': 'Las fintech islámicas crecen en el CCG, Malasia, Indonesia y Pakistán, con robos conformes a la sharía y acceso a sukuk.',
    'brokers.trends.8': 'Los rieles de pago deciden quién gana. Pix, UPI, SPEI, QRIS, GCash, M-Pesa y NIP hacen viable invertir con tickets pequeños.',
    'brokers.trends.9': 'Los brókers despliegan copilotos de IA para investigación y soporte mientras los reguladores vigilan la frontera entre información y asesoramiento.',
    'brokers.trends.10': 'El acceso transfronterizo se endurece y se relaja a la vez, y la ciberseguridad y el fraude de inversión siguen creciendo.',

    'brokers.sources.title': 'Fuentes y método',
    'brokers.sources.p1': 'Compilado a partir de “Brokers & Trading Apps in Emerging Markets”, un informe de investigación documental fechado el 2 de noviembre de 2026. Es un mapa del sector, no un ranking ni asesoramiento de inversión.',
    'brokers.sources.p2': 'Las fuentes primarias fueron informes de empresas, registros de reguladores, datos de exchanges y prensa financiera reputada (referencias S1–S38 del informe). Las cifras son las últimas divulgadas o reportadas y no se auditaron aquí.',
    'brokers.sources.p3': 'Las comisiones y la disponibilidad de productos cambian con frecuencia. Verifica la entidad legal, la licencia, la tarifa vigente y el tratamiento fiscal antes de fondear cualquier cuenta.',
    'brokers.sources.p4': 'TIKOTrade es solo informativo. Esta página no abre cuentas, no ejecuta órdenes, no sigue carteras ni envía alertas de precio. La app no tiene conexión con ningún bróker.',
    'brokers.sources.registers': 'Registros oficiales',

